function formatDuration(seconds: number) {
    if (seconds <= 0) return "0s";

    const units = [
        { name: 'a', seconds: 31536000 }, // año
        { name: 'mes', seconds: 2592000 },
        { name: 'd', seconds: 86400 }, // día
        { name: 'h', seconds: 3600 },
